c.python:
class Solution:
    def alternatingSum(self, nums: list[int]) -> int:
        ans, sign = 0, 1
        for x in nums:
            ans += sign * x
            sign = -sign
        return ans

c.cpp:
class Solution {
public:
    int alternatingSum(vector<int>& nums) {
        int ans = 0, sign = 1;
        for (int x : nums) { ans += sign * x; sign = -sign; }
        return ans;
    }
};

